import org.owasp.webgoat.container.assignments.AssignmentHints;
import org.owasp.webgoat.container.assignments.AttackResult;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@AssignmentHints({"password-storage.stage1.hint1", "password-storage.stage1.hint2"})
public class Stage1HashAssignment implements AssignmentEndpoint {

  @PostMapping("/PasswordStorage/stage1")
  public AttackResult submit(@RequestParam(defaultValue = "") String password) {
    if (java.security.MessageDigest.isEqual(PasswordStorageService.AUTHOR_PASSWORD.getBytes(), password.getBytes())) {
