resource "google_storage_bucket" "terraform_state_storage_bucket" {
  name                        = "cicd-terraform-state"
  location                    = "us"
  storage_class               = "STANDARD"
  force_destroy               = false
  public_access_prevention    = "enforced"
  uniform_bucket_level_access = true
  versioning {
    enabled = true
  }
}

